# patch_20260916_openai_llm.ps1
# Switch URM text generation from the Anthropic API to the OpenAI API (cost).
# - adds src/lib/ai/openai-chat.ts, rewires ClaudeClient + email-compose to OpenAI
# - env: ANTHROPIC_* optional, OPENAI_MODEL_OPUS/SONNET/HAIKU (defaults gpt-5-mini/gpt-5-mini/gpt-5-nano)
# Safe + idempotent: each file is written only if it still matches the GitHub
# version (commit 17ecb34). Already patched -> SKIP. Locally edited -> WARN, untouched.
# ASCII only. PS 5.x compatible. Repo = C:\dev\mbg-project
$ErrorActionPreference = 'Stop'
$repo = 'C:\dev\mbg-project'
$utf8 = New-Object System.Text.UTF8Encoding($false)
$sha = [System.Security.Cryptography.SHA256]::Create()
function HashOf([byte[]]$b) { return (($sha.ComputeHash($b) | ForEach-Object { $_.ToString('x2') }) -join '') }
function LocalHash([string]$p) {
  $b = [System.IO.File]::ReadAllBytes($p)
  if ($b.Length -ge 3 -and $b[0] -eq 0xEF -and $b[1] -eq 0xBB -and $b[2] -eq 0xBF) { $b = $b[3..($b.Length-1)] }
  $s = $utf8.GetString($b) -replace "`r`n", "`n"
  return (HashOf ($utf8.GetBytes($s)))
}
$ok = 0; $skip = 0; $warn = 0
function Put([string]$rel, [string]$oldHash, [string]$newHash, [string]$b64) {
  $p = [System.IO.Path]::Combine($script:repo, $rel)
  $bytes = [Convert]::FromBase64String($b64)
  if ([System.IO.File]::Exists($p)) {
    $cur = LocalHash $p
    if ($cur -eq $newHash) { Write-Host "[SKIP] $rel (already applied)"; $script:skip++; return }
    if ($cur -ne $oldHash) { Write-Host "[WARN] $rel differs from GitHub version - NOT changed"; $script:warn++; return }
  } elseif ($oldHash -ne 'NEW') {
    Write-Host "[WARN] $rel not found - NOT changed"; $script:warn++; return
  }
  [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($p)) | Out-Null
  [System.IO.File]::WriteAllBytes($p, $bytes)
  Write-Host "[OK]   $rel"; $script:ok++
}
if (-not (Test-Path -LiteralPath $repo)) { Write-Host "ERROR repo not found: $repo"; return }

